import java.math.BigDecimal
import java.math.RoundingMode

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    private fun normalize(amount: BigDecimal): BigDecimal {
        require(amount.scale() <= 2) { "amount has more than 2 decimal places: $amount" }
        return amount.setScale(2, RoundingMode.UNNECESSARY)
    }

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        require(!balances.containsKey(id)) { "account already exists: $id" }
        val amount = normalize(initial)
        require(amount.signum() >= 0) { "initial balance must not be negative" }
        balances[id] = amount
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal =
        balances[id] ?: throw NoSuchElementException("no such account: $id")

    fun transfer(from: String, to: String, amount: BigDecimal) {
        val a = normalize(amount)
        require(a.signum() > 0) { "amount must be positive" }
        val fromBalance = balances[from] ?: throw NoSuchElementException("no such account: $from")
        val toBalance = balances[to] ?: throw NoSuchElementException("no such account: $to")
        if (fromBalance < a) throw IllegalStateException("insufficient funds")
        balances[from] = fromBalance - a
        balances[to] = toBalance + a
        log.getValue(from).add(a.negate())
        log.getValue(to).add(a)
    }

    fun history(id: String): List<BigDecimal> =
        log[id]?.toList() ?: throw NoSuchElementException("no such account: $id")

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            require(n > 0) { "n must be positive" }
            val t = normalize(total)
            require(t.signum() >= 0) { "total must not be negative" }
            val base = t.divide(BigDecimal(n), 0, RoundingMode.DOWN)
            val remainder = t.subtract(base.multiply(BigDecimal(n))).movePointRight(2).toInt()
            val result = ArrayList<BigDecimal>(n)
            for (i in 0 until n) {
                val part = if (i < remainder) base.add(BigDecimal("0.01")) else base
                result.add(part.setScale(2, RoundingMode.UNNECESSARY))
            }
            return result
        }
    }
}
