class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {

    init {
        require(capacity >= 1) { "capacity must be >= 1, was $capacity" }
    }

    private class Node<K, V>(val key: K, var value: V) {
        var prev: Node<K, V>? = null
        var next: Node<K, V>? = null
    }

    private val map = HashMap<K, Node<K, V>>()

    // Sentinel head (least recently used side) and tail (most recently used side).
    private val head = Node<K, V>(Any() as K, Any() as V)
    private val tail = Node<K, V>(Any() as K, Any() as V)

    init {
        head.next = tail
        tail.prev = head
    }

    val size: Int
        get() = map.size

    private fun unlink(node: Node<K, V>) {
        val p = node.prev
        val n = node.next
        p?.next = n
        n?.prev = p
        node.prev = null
        node.next = null
    }

    private fun linkToTail(node: Node<K, V>) {
        val last = tail.prev!!
        last.next = node
        node.prev = last
        node.next = tail
        tail.prev = node
    }

    private fun moveToTail(node: Node<K, V>) {
        unlink(node)
        linkToTail(node)
    }

    operator fun get(key: K): V? {
        val node = map[key] ?: return null
        moveToTail(node)
        return node.value
    }

    operator fun set(key: K, value: V) {
        val existing = map[key]
        if (existing != null) {
            existing.value = value
            moveToTail(existing)
            return
        }
        val node = Node(key, value)
        map[key] = node
        linkToTail(node)
        if (map.size > capacity) {
            val lru = head.next!!
            unlink(lru)
            map.remove(lru.key)
            onEvict(lru.key, lru.value)
        }
    }

    fun remove(key: K): V? {
        val node = map.remove(key) ?: return null
        unlink(node)
        return node.value
    }

    fun keys(): List<K> {
        val result = ArrayList<K>(map.size)
        var cur = head.next
        while (cur !== tail) {
            result.add(cur!!.key)
            cur = cur.next
        }
        return result
    }

    operator fun contains(key: K): Boolean = map.containsKey(key)
}
