```kotlin
fun toJson(value: Any?, indent: Int = 0): String {
    val sb = StringBuilder()
    writeValue(sb, value, indent, 0)
    return sb.toString()
}

private fun writeValue(sb: StringBuilder, value: Any?, indent: Int, level: Int) {
    when (value) {
        null -> sb.append("null")
        is Boolean -> sb.append(value.toString())
        is String -> writeString(sb, value)
        is Int -> sb.append(value.toString())
        is Long -> sb.append(value.toString())
        is Double -> writeDouble(sb, value)
        is Float -> {
            val d = value.toDouble()
            if (d.isNaN() || d.isInfinite()) throw IllegalArgumentException("Non-finite number: $value")
            sb.append(value.toString())
        }
        is Enum<*> -> writeString(sb, value.name)
        is Map<*, *> -> writeMap(sb, value, indent, level)
        is List<*> -> writeList(sb, value, indent, level)
        is Array<*> -> writeList(sb, value.asList(), indent, level)
        else -> throw IllegalArgumentException("Unsupported type: ${value::class}")
    }
}

private fun writeDouble(sb: StringBuilder, value: Double) {
    if (value.isNaN() || value.isInfinite()) throw IllegalArgumentException("Non-finite number: $value")
    sb.append(value.toString())
}

private fun writeString(sb: StringBuilder, s: String) {
    sb.append('"')
    for (c in s) {
        when (c) {
            '"' -> sb.append("\\\"")
            '\\' -> sb.append("\\\\")
            '\b' -> sb.append("\\b")
            '\u000C' -> sb.append("\\f")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            else -> {
                if (c < ' ') {
                    sb.append("\\u00")
                    sb.append(HEX[(c.code shr 4) and 0xF])
                    sb.append(HEX[c.code and 0xF])
                } else {
                    sb.append(c)
                }
            }
        }
    }
    sb.append('"')
}

private val HEX = "0123456789abcdef"

private fun writeMap(sb: StringBuilder, map: Map<*, *>, indent: Int, level: Int) {
    if (map.isEmpty()) {
        sb.append("{}")
        return
    }
    sb.append('{')
    var first = true
    for ((k, v) in map) {
        if (k !is String) throw IllegalArgumentException("Map keys must be String: $k")
        if (!first) sb.append(',')
        first = false
        if (indent > 0) {
            sb.append('\n')
            appendIndent(sb, indent, level + 1)
        }
        writeString(sb, k)
        sb.append(':')
        if (indent > 0) sb.append(' ')
        writeValue(sb, v, indent, level + 1)
    }
    if (indent > 0) {
        sb.append('\n')
        appendIndent(sb, indent, level)
    }
    sb.append('}')
}

private fun writeList(sb: StringBuilder, list: List<*>, indent: Int, level: Int) {
    if (list.isEmpty()) {
        sb.append("[]")
        return
    }
    sb.append('[')
    var first = true
    for (v in list) {
        if (!first) sb.append(',')
        first = false
        if (indent > 0) {
            sb.append('\n')
            appendIndent(sb, indent, level + 1)
        }
        writeValue(sb, v, indent, level + 1)
    }
    if (indent > 0) {
        sb.append('\n')
        appendIndent(sb, indent, level)
    }
    sb.append(']')
}

private fun appendIndent(sb: StringBuilder, indent: Int, level: Int) {
    val count = indent * level
    for (i in 0 until count) sb.append(' ')
}
