sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}
class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val n = input.length

    fun isIdentStart(c: Char) = (c in 'A'..'Z') || (c in 'a'..'z') || c == '_'
    fun isIdentPart(c: Char) = isIdentStart(c) || (c in '0'..'9') || c == '.'
    fun isDigit(c: Char) = c in '0'..'9'

    fun canBeMinus(): Boolean {
        val prev = tokens.lastOrNull()
        return prev == null ||
            prev is Token.Op ||
            (prev is Token.Paren && prev.open)
    }

    while (i < n) {
        val c = input[i]
        when {
            c == ' ' || c == '\t' || c == '\n' -> {
                i++
            }
            isIdentStart(c) -> {
                val start = i
                i++
                while (i < n && isIdentPart(input[i])) i++
                tokens.add(Token.Ident(input.substring(start, i), start))
            }
            isDigit(c) -> {
                val start = i
                while (i < n && isDigit(input[i])) i++
                if (i < n && input[i] == '.') {
                    i++
                    if (i >= n || !isDigit(input[i])) {
                        throw TokenizeException("Malformed number", start)
                    }
                    while (i < n && isDigit(input[i])) i++
                }
                val text = input.substring(start, i)
                val value = text.toDoubleOrNull()
                    ?: throw TokenizeException("Malformed number", start)
                tokens.add(Token.Num(value, start))
            }
            c == '-' -> {
                if (!canBeMinus()) {
                    throw TokenizeException("Unexpected '-'", i)
                }
                val start = i
                i++
                if (i >= n || !isDigit(input[i])) {
                    throw TokenizeException("Malformed number", start)
                }
                while (i < n && isDigit(input[i])) i++
                if (i < n && input[i] == '.') {
                    i++
                    if (i >= n || !isDigit(input[i])) {
                        throw TokenizeException("Malformed number", start)
                    }
                    while (i < n && isDigit(input[i])) i++
                }
                val text = input.substring(start, i)
                val value = text.toDoubleOrNull()
                    ?: throw TokenizeException("Malformed number", start)
                tokens.add(Token.Num(value, start))
            }
            c == '"' || c == '\'' -> {
                val start = i
                val quote = c
                i++
                val sb = StringBuilder()
                var closed = false
                while (i < n) {
                    val ch = input[i]
                    if (ch == '\\') {
                        if (i + 1 >= n) {
                            throw TokenizeException("Unterminated string", start)
                        }
                        val esc = input[i + 1]
                        if (esc == 'n') sb.append('\n') else sb.append(esc)
                        i += 2
                    } else if (ch == quote) {
                        i++
                        closed = true
                        break
                    } else {
                        sb.append(ch)
                        i++
                    }
                }
                if (!closed) {
                    throw TokenizeException("Unterminated string", start)
                }
                tokens.add(Token.Str(sb.toString(), start))
            }
            c == '(' || c == ')' -> {
                tokens.add(Token.Paren(c == '(', i))
                i++
            }
            c == '=' || c == '!' || c == '<' || c == '>' -> {
                val start = i
                val next = if (i + 1 < n) input[i + 1] else '\u0000'
                when {
                    c == '=' && next == '=' -> { tokens.add(Token.Op("==", start)); i += 2 }
                    c == '!' && next == '=' -> { tokens.add(Token.Op("!=", start)); i += 2 }
                    c == '<' && next == '=' -> { tokens.add(Token.Op("<=", start)); i += 2 }
                    c == '>' && next == '=' -> { tokens.add(Token.Op(">=", start)); i += 2 }
                    c == '<' -> { tokens.add(Token.Op("<", start)); i += 1 }
                    c == '>' -> { tokens.add(Token.Op(">", start)); i += 1 }
                    c == '!' -> { tokens.add(Token.Op("!", start)); i += 1 }
                    else -> throw TokenizeException("Unexpected character '$c'", i)
                }
            }
            c == '&' -> {
                if (i + 1 < n && input[i + 1] == '&') {
                    tokens.add(Token.Op("&&", i))
                    i += 2
                } else {
                    throw TokenizeException("Unexpected character '&'", i)
                }
            }
            c == '|' -> {
                if (i + 1 < n && input[i + 1] == '|') {
                    tokens.add(Token.Op("||", i))
                    i += 2
                } else {
                    throw TokenizeException("Unexpected character '|'", i)
                }
            }
            else -> {
                throw TokenizeException("Unexpected character '$c'", i)
            }
        }
    }
    return tokens
}
