import asyncio


async def gather_limited(factories, limit: int, timeout: float | None = None) -> list:
    if limit < 1:
        raise ValueError("limit must be at least 1")
    n = len(factories)
    if n == 0:
        return []

    results = [None] * n
    tasks: dict[asyncio.Task, int] = {}
    first_exc = None

    async def runner(idx: int):
        coro = factories[idx]()
        awaitable = asyncio.ensure_future(coro)
        if timeout is None:
            return await awaitable
        try:
            return await asyncio.wait_for(awaitable, timeout)
        except asyncio.TimeoutError:
            raise asyncio.TimeoutError()

    next_idx = 0
    try:
        while next_idx < n and len(tasks) < limit:
            t = asyncio.ensure_future(runner(next_idx))
            tasks[t] = next_idx
            next_idx += 1

        while tasks:
            done, _ = await asyncio.wait(
                tasks.keys(), return_when=asyncio.FIRST_COMPLETED
            )
            for t in done:
                idx = tasks.pop(t)
                if t.cancelled():
                    continue
                exc = t.exception()
                if exc is not None:
                    if first_exc is None:
                        first_exc = exc
                else:
                    results[idx] = t.result()

            if first_exc is not None:
                break

            while next_idx < n and len(tasks) < limit:
                t = asyncio.ensure_future(runner(next_idx))
                tasks[t] = next_idx
                next_idx += 1
    except asyncio.CancelledError:
        for t in tasks:
            t.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        raise

    if first_exc is not None:
        for t in tasks:
            t.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        raise first_exc

    return results
