import datetime
import re

MONTH_NAMES = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}
DAY_NAMES = {
    "SUN": 0, "MON": 1, "TUE": 2, "WED": 3, "THU": 4, "FRI": 5, "SAT": 6,
}

FIELD_BOUNDS = [
    (0, 59),   # minute
    (0, 23),   # hour
    (1, 31),   # day-of-month
    (1, 12),   # month
    (0, 7),    # day-of-week
]


def _parse_value(token, field_index):
    lo, hi = FIELD_BOUNDS[field_index]
    t = token.upper()
    if field_index == 3:
        if t in MONTH_NAMES:
            return MONTH_NAMES[t]
    if field_index == 4:
        if t in DAY_NAMES:
            return DAY_NAMES[t]
    if not re.fullmatch(r"\d+", token):
        raise ValueError("Unknown name: %r" % token)
    v = int(token)
    if v < lo or v > hi:
        raise ValueError("Value out of range: %r" % token)
    return v


def _parse_field(field, field_index):
    lo, hi = FIELD_BOUNDS[field_index]
    values = set()
    for item in field.split(","):
        if item == "":
            raise ValueError("Empty item in field %r" % field)
        step = None
        base = item
        if "/" in item:
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError("Bad step syntax: %r" % item)
            base, step_str = parts
            if not re.fullmatch(r"\d+", step_str):
                raise ValueError("Bad step: %r" % step_str)
            step = int(step_str)
            if step == 0:
                raise ValueError("Zero step: %r" % item)

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            parts = base.split("-")
            if len(parts) != 2:
                raise ValueError("Bad range: %r" % base)
            start = _parse_value(parts[0], field_index)
            end = _parse_value(parts[1], field_index)
            if start > end:
                raise ValueError("Range A > B: %r" % base)
        else:
            start = _parse_value(base, field_index)
            if step is None:
                end = start
            else:
                end = hi

        if step is None:
            step = 1
        for v in range(start, end + 1, step):
            values.add(v)
    return values


def _normalize_dow(values):
    result = set()
    for v in values:
        result.add(0 if v == 7 else v)
    return result


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expected 5 fields, got %d" % len(fields))

    minutes = _parse_field(fields[0], 0)
    hours = _parse_field(fields[1], 1)
    doms = _parse_field(fields[2], 2)
    months = _parse_field(fields[3], 3)
    dows = _normalize_dow(_parse_field(fields[4], 4))

    dom_star = fields[2] == "*"
    dow_star = fields[4] == "*"
    dom_restricted = not dom_star
    dow_restricted = not dow_star

    # Start from the next whole minute strictly after `after`.
    start = after.replace(second=0, microsecond=0)
    if start <= after:
        start += datetime.timedelta(minutes=1)
    else:
        # after had seconds/micros == 0 and start == after -> must advance
        start += datetime.timedelta(minutes=1)

    limit = after + datetime.timedelta(days=365 * 5)
    # Hard cap on iterations to guarantee termination.
    max_iter = 5 * 366 * 24 * 60 + 10

    dt = start
    for _ in range(max_iter):
        if dt > limit:
            break

        if dt.month not in months:
            # jump to first day of next month
            if dt.month == 12:
                dt = datetime.datetime(dt.year + 1, 1, 1, 0, 0)
            else:
                dt = datetime.datetime(dt.year, dt.month + 1, 1, 0, 0)
            continue

        # day match
        dom_ok = dt.day in doms
        dow_ok = (dt.weekday() + 1) % 7 in dows  # Monday=0 -> Sunday=0
        if dom_restricted and dow_restricted:
            day_ok = dom_ok or dow_ok
        else:
            day_ok = dom_ok and dow_ok

        if not day_ok:
            dt = datetime.datetime(dt.year, dt.month, dt.day) + datetime.timedelta(days=1)
            continue

        if dt.hour not in hours:
            dt = datetime.datetime(dt.year, dt.month, dt.day, dt.hour) + datetime.timedelta(hours=1)
            continue

        if dt.minute not in minutes:
            dt += datetime.timedelta(minutes=1)
            continue

        return dt

    raise ValueError("No matching time found within 5 years")
