import copy


def merge(base: dict, *overrides: dict) -> dict:
    result = copy.deepcopy(base)

    for override in overrides:
        result = _merge_into(result, override)

    return result


def _merge_into(base: dict, override: dict) -> dict:
    result = copy.deepcopy(base)

    for key, value in override.items():
        if key.endswith("+") and len(key) > 1:
            target_key = key[:-1]
            if value is None:
                # Deleting via an append key is ambiguous; treat as delete of target.
                result.pop(target_key, None)
                continue

            items = list(value) if isinstance(value, (list, tuple)) else [value]

            if target_key in result and result[target_key] is not None:
                existing = result[target_key]
                if not isinstance(existing, list):
                    raise TypeError(
                        f"Cannot append to {target_key!r}: base value is not a list"
                    )
                result[target_key] = copy.deepcopy(existing) + copy.deepcopy(items)
            else:
                result[target_key] = copy.deepcopy(items)

        elif value is None:
            result.pop(key, None)

        elif isinstance(value, dict):
            current = result.get(key)
            if isinstance(current, dict):
                result[key] = _merge_into(current, value)
            else:
                result[key] = _merge_into({}, value)

        else:
            result[key] = copy.deepcopy(value)

    return result
