import re

_UNITS = ['d', 'h', 'm', 's']
_UNIT_SECONDS = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
_UNIT_ORDER = {u: i for i, u in enumerate(_UNITS)}

_PART_RE = re.compile(r'(\d+)([a-zA-Z])')
_VALID_RE = re.compile(r'^\d+[dhm sD HMS]?$', re.IGNORECASE)  # placeholder, unused


def parse_duration(s: str) -> int:
    if not isinstance(s, str) or s == '':
        raise ValueError("empty input")

    # Reject characters outside digits, units, and single separating spaces.
    # We parse part by part to enforce spacing rules strictly.

    i = 0
    n = len(s)
    last_order = -1
    seen = set()
    total = 0
    found_any = False
    expect_part = True

    while i < n:
        # At a part boundary we must have a digit.
        if not s[i].isdigit():
            raise ValueError("missing number")
        start = i
        while i < n and s[i].isdigit():
            i += 1
        number_str = s[start:i]
        if i >= n:
            raise ValueError("missing unit")
        unit_char = s[i]
        i += 1
