    result = {}

    # Each entry in assignments: (parent_container_ref, segment, value)
    # We'll build using a tree of nodes first to detect conflicts cleanly.
    # Node types: 'value', 'dict', 'list'
    root = {"type": "dict", "children": {}}

    for key, value in flat.items():
        if not isinstance(key, str):
            raise ValueError("keys must be strings")
        if key == "":
            raise ValueError("empty key")
        segments = key.split(sep)
        for seg in segments:
            if seg == "":
                raise ValueError("empty path segment")

        node = root
        for seg in segments:
            if _is_list_index(seg):
                if node["type"] == "value":
                    raise ValueError("conflict")
                if node["type"] == "dict":
                    if node["children"]:
                        # dict node with children can't become list
                        raise ValueError("conflict")
                    node["type"] = "list"
                    node["children"] = {}
                # list node
                idx = int(seg)
                children = node["children"]
                if idx in children:
                    child = children[idx]
                else:
                    child = {"type": None, "children": {}}
                    children[idx] = child
                node = child
            else:
                if node["type"] == "value":
                    raise ValueError("conflict")
                if node["type"] == "list":
                    raise ValueError("conflict")
                if node["type"] is None:
                    node["type"] = "dict"
                children = node["children"]
                if seg in children:
                    child = children[seg]
                else:
                    child = {"type": None, "children": {}}
                    children[seg] = child
                node = child

        if node["type"] == "value":
            raise ValueError("conflict")
        if node["children"]:
            raise ValueError("conflict")
        node["type"] = "value"
        node["value"] = value

    def build(node):
        t = node["type"]
        if t == "value":
            return node["value"]
        if t == "dict":
            return {k: build(v) for k, v in node["children"].items()}
        if t == "list":
            children = node["children"]
            n = len(children)
            if set(children.keys()) != set(range(n)):
                raise ValueError("lists must be dense")
            return [build(children[i]) for i in range(n)]
        if t is None:
            # shouldn't happen at top since top is dict; treat as empty dict
            return {}
        raise ValueError("invalid node")

    return build(root)
