import re

_TOKEN_RE = re.compile(r"""
    \s*(?:
        (?P<num>\d+\.\d*|\.\d+|\d+)
      | (?P<id>[A-Za-z_][A-Za-z0-9_]*)
      | (?P<op>\|\||&&|==|!=|<=|>=|[<>+\-*/%^!?:()=,&|])
    )
""", re.VERBOSE)


def _tokenize(expr):
    tokens = []
    pos = 0
    n = len(expr)
    while pos < n:
        m = _TOKEN_RE.match(expr, pos)
        if not m or m.end() == pos:
            if expr[pos:].strip() == "":
                break
            raise SyntaxError("invalid character at %d" % pos)
        pos = m.end()
        if m.group("num") is not None:
            s = m.group("num")
            if "." in s:
                tokens.append(("num", float(s)))
            else:
                tokens.append(("num", int(s)))
        elif m.group("id") is not None:
            tokens.append(("id", m.group("id")))
        else:
            op = m.group("op")
            if op in ("=", "&", "|"):
                raise SyntaxError("invalid token %r" % op)
            tokens.append(("op", op))
    tokens.append(("eof", None))
    return tokens


class _Parser:
    def __init__(self, tokens, env):
        self.tokens = tokens
        self.pos = 0
        self.env = env

    def peek(self):
        return self.tokens[self.pos]

    def advance(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def is_op(self, *ops):
        t = self.peek()
        return t[0] == "op" and t[1] in ops

    def expect_op(self, op):
        if not self.is_op(op):
            raise SyntaxError("expected %r" % op)
        self.advance()

    def parse(self):
        val = self.conditional()
        if self.peek()[0] != "eof":
            raise SyntaxError("trailing tokens")
        return val

    def conditional(self):
        cond = self.logical_or()
        if self.is_op("?"):
            self.advance()
            a = self.conditional()
            self.expect_op(":")
            b = self.conditional()
            return a if cond != 0 else b
        return cond

    def logical_or(self):
        val = self.logical_and()
        while self.is_op("||"):
            self.advance()
            rhs = self.logical_and()
            val = 1 if (val != 0 or rhs != 0) else 0
        return val

    def logical_and(self):
        val = self.comparison()
        while self.is_op("&&"):
            self.advance()
            rhs = self.comparison()
            val = 1 if (val != 0 and rhs != 0) else 0
        return val

    def comparison(self):
        val = self.additive()
        ops = ("==", "!=", "<", "<=", ">", ">=")
        if self.is_op(*ops):
            op = self.advance()[1]
            rhs = self.additive()
            if self.is_op(*ops):
                raise SyntaxError("chained comparison")
            if op == "==":
                val = 1 if val == rhs else 0
            elif op == "!=":
                val = 1 if val != rhs else 0
            elif op == "<":
                val = 1 if val < rhs else 0
            elif op == "<=":
                val = 1 if val <= rhs else 0
            elif op == ">":
                val = 1 if val > rhs else 0
            else:
                val = 1 if val >= rhs else 0
        return val

    def additive(self):
        val = self.multiplicative()
        while self.is_op("+", "-"):
            op = self.advance()[1]
            rhs = self.multiplicative()
            val = val + rhs if op == "+" else val - rhs
        return val

    def multiplicative(self):
        val = self.unary()
        while self.is_op("*", "/", "%"):
            op = self.advance()[1]
            rhs = self.unary()
            if op == "*":
                val = val * rhs
            elif op == "/":
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                if isinstance(val, int) and isinstance(rhs, int):
                    if val % rhs == 0:
                        val = val // rhs
                    else:
                        val = val / rhs
                else:
                    val = val / rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("modulo by zero")
                val = val % rhs
        return val

    def unary(self):
        if self.is_op("-"):
            self.advance()
            v = self.unary()
            return -v
        if self.is_op("+"):
            self.advance()
            return self.unary()
        if self.is_op("!"):
            self.advance()
            v = self.unary()
            return 1 if v == 0 else 0
        return self.power()

    def power(self):
        base = self.atom()
        if self.is_op("^"):
            self.advance()
            exp = self.unary()
            return base ** exp
        return base

    def atom(self):
        t = self.peek()
        if t[0] == "num":
            self.advance()
            return t[1]
        if t[0] == "id":
            name = t[1]
            self.advance()
            if self.is_op("("):
                self.advance()
                args = [self.conditional()]
                while self.is_op(","):
                    self.advance()
                    args.append(self.conditional())
                self.expect_op(")")
                return self.call(name, args)
            if self.env is None or name not in self.env:
                raise NameError("unknown variable %r" % name)
            return self.env[name]
        if t[0] == "op" and t[1] == "(":
            self.advance()
            val = self.conditional()
            self.expect_op(")")
            return val
        raise SyntaxError("unexpected token")

    def call(self, name, args):
        if name == "abs":
            if len(args) != 1:
                raise SyntaxError("abs takes 1 argument")
            return abs(args[0])
        if name == "min":
            if len(args) < 1:
                raise SyntaxError("min takes at least 1 argument")
            return min(args)
        if name == "max":
            if len(args) < 1:
                raise SyntaxError("max takes at least 1 argument")
            return max(args)
        raise NameError("unknown function %r" % name)


def evaluate(expr, env=None):
    tokens = _tokenize(expr)
    if len(tokens) == 1:
        raise SyntaxError("empty input")
    return _Parser(tokens, env).parse()
