            v = self.unary()
            return -v
        if self.is_op("+"):
            self.advance()
            return self.unary()
        if self.is_op("!"):
            self.advance()
            v = self.unary()
            return 1 if v == 0 else 0
        return self.power()

    def power(self):
        base = self.atom()
        if self.is_op("^"):
            self.advance()
            exp = self.unary()
            return base ** exp
        return base

    def atom(self):
        t = self.peek()
        if t[0] == "num":
            self.advance()
            return t[1]
        if t[0] == "id":
            name = t[1]
            self.advance()
            if self.is_op("("):
                self.advance()
                args = [self.conditional()]
                while self.is_op(","):
                    self.advance()
                    args.append(self.conditional())
                self.expect_op(")")
                return self.call(name, args)
            if self.env is None or name not in self.env:
                raise NameError("unknown variable %r" % name)
            return self.env[name]
        if t[0] == "op" and t[1] == "(":
            self.advance()
            val = self.conditional()
            self.expect_op(")")
            return val
        raise SyntaxError("unexpected token")

    def call(self, name, args):
        if name == "abs":
            if len(args) != 1:
                raise SyntaxError("abs takes 1 argument")
            return abs(args[0])
        if name == "min":
            if len(args) < 1:
                raise SyntaxError("min takes at least 1 argument")
            return min(args)
        if name == "max":
            if len(args) < 1:
                raise SyntaxError("max takes at least 1 argument")
            return max(args)
        raise NameError("unknown function %r" % name)


def evaluate(expr, env=None):
    tokens = _tokenize(expr)
    if len(tokens) == 1:
        raise SyntaxError("empty input")
    return _Parser(tokens, env).parse()
