from heapq import heappush, heappop


def route(grid: list[str]) -> tuple[int, str] | None:
    # ---- validation ----
    if not isinstance(grid, list):
        raise ValueError("grid must be a list of strings")
    if not grid:
        raise ValueError("empty grid")
    n = len(grid)
    m = len(grid[0])
    if m == 0:
        raise ValueError("empty row")
    for row in grid:
        if not isinstance(row, str):
            raise ValueError("rows must be strings")
        if len(row) != m:
            raise ValueError("ragged rows")

    start = end = None
    pad_pos = {}
    pad_count = {}
    for r in range(n):
        for c in range(m):
            ch = grid[r][c]
            if ch == 'S':
                if start is not None:
                    raise ValueError("multiple S")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("multiple E")
                end = (r, c)
            elif ch == '#':
                pass
            elif ch == '.':
                pass
            elif '1' <= ch <= '9':
                pass
            elif 'a' <= ch <= 'z':
                pad_pos.setdefault(ch, []).append((r, c))
                pad_count[ch] = pad_count.get(ch, 0) + 1
            else:
                raise ValueError(f"unknown character {ch!r}")

    if start is None:
        raise ValueError("no S")
    if end is None:
        raise ValueError("no E")
    for ch, cnt in pad_count.items():
        if cnt != 2:
            raise ValueError(f"pad {ch!r} appears {cnt} times")

    pad_partner = {}
    for ch, positions in pad_pos.items():
        a, b = positions
        pad_partner[a] = b
        pad_partner[b] = a

    def cell_cost(r, c):
        ch = grid[r][c]
        if '1' <= ch <= '9':
            return ord(ch) - ord('0')
        return 1

    # ---- Dijkstra with lexicographic tie-breaking ----
    # moves ordered D < L < R < T < U
    # each move: (dr, dc, letter, is_teleport)
    DELTAS = [
        (1, 0, 'D', False),
        (0, -1, 'L', False),
        (0, 1, 'R', False),
        (0, 0, 'T', True),
        (-1, 0, 'U', False),
    ]

    INF = float('inf')
    dist = [[INF] * m for _ in range(n)]
    # path string for each cell
    best_path = [[None] * m for _ in range(n)]

    sr, sc = start
    dist[sr][sc] = 0
    best_path[sr][sc] = ""

    # heap entries: (cost, path_string, r, c)
    # path_string comparison implements lexicographic tie-break among equal costs
    heap = [(0, "", sr, sc)]

    while heap:
        d, p, r, c = heappop(heap)
        if d > dist[r][c]:
            continue
        if best_path[r][c] is not None and (d, p) != (dist[r][c], best_path[r][c]):
            # stale entry (worse path with same cost)
            continue
        if (r, c) == end:
            return (d, p)

        for dr, dc, letter, is_tp in DELTAS:
            if is_tp:
                if (r, c) not in pad_partner:
                    continue
                nr, nc = pad_partner[(r, c)]
                nd = d + 2
            else:
                nr, nc = r + dr, c + dc
                if nr < 0 or nr >= n or nc < 0 or nc >= m:
                    continue
                if grid[nr][nc] == '#':
                    continue
                nd = d + cell_cost(nr, nc)

            np_ = p + letter
            cur = dist[nr][nc]
            if nd < cur or (nd == cur and (best_path[nr][nc] is None or np_ < best_path[nr][nc])):
                dist[nr][nc] = nd
                best_path[nr][nc] = np_
                heappush(heap, (nd, np_, nr, nc))

    return None
