import re


def load_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.split('\n')

    def strip_inline_comment(line: str) -> str:
        in_quotes = False
        i = 0
        n = len(line)
        while i < n:
            c = line[i]
            if c == '\\' and in_quotes and i + 1 < n and line[i+1] == '"':
                i += 2
                continue
            if c == '"':
                in_quotes = not in_quotes
                i += 1
                continue
            if not in_quotes and c in (';', '#') and i > 0 and line[i-1] in (' ', '\t'):
                return line[:i]
            i += 1
        return line

    entries = []
    current_section = ""
    last_entry = None

    for idx, raw_line in enumerate(lines):
        line_no = idx + 1
        line = raw_line.rstrip('\r')

        if line.strip() == '':
            last_entry = None
            continue

        if line[0] in (' ', '\t') and last_entry is not None:
            cont = strip_inline_comment(line).strip()
            if cont != '':
                last_entry['parts'].append(cont)
            continue

        if line[0] in (' ', '\t') and last_entry is None:
            raise ValueError(f"line {line_no}: continuation line with no preceding entry")

        stripped = line.strip()

        if stripped.startswith('#') or stripped.startswith(';'):
            continue

        if stripped.startswith('['):
            close = stripped.find(']')
            if close == -1:
                raise ValueError(f"line {line_no}: unclosed [")
            current_section = stripped[1:close].strip()
            last_entry = None
            continue

        eq = stripped.find('=')
        colon = stripped.find(':')
        if eq == -1 and colon == -1:
            raise ValueError(f"line {line_no}: missing separator")
        if eq == -1:
            sep_idx = colon
        elif colon == -1:
            sep_idx = eq
        else:
            sep_idx = min(eq, colon)

        key = stripped[:sep_idx].strip().lower()
        value_raw = strip_inline_comment(stripped[sep_idx+1:]).strip()

        entry = {
            'section': current_section,
            'key': key,
            'parts': [value_raw],
            'line_no': line_no,
        }
        entries.append(entry)
        last_entry = entry

    sections_final: dict[str, dict[str, str]] = {}
    for e in entries:
        sec = e['section']
        if sec not in sections_final:
            sections_final[sec] = {}
        raw_value = '\n'.join(e['parts'])
        sections_final[sec][e['key']] = raw_value

    if '' in sections_final and not sections_final['']:
        del sections_final['']

    def process_quotes(val: str, line_no: int) -> str:
        if len(val) >= 2 and val[0] == '"' and val[-1] == '"':
            inner = val[1:-1]
            result = []
            i = 0
            while i < len(inner):
                c = inner[i]
                if c == '\\' and i+1 < len(inner) and inner[i+1] == '"':
                    result.append('"')
                    i += 2
                    continue
                result.append(c)
                i += 1
            return ''.join(result)
        else:
            if val.startswith('"'):
                raise ValueError(f"line {line_no}: unterminated quote")
            cnt = 0
            i = 0
            while i < len(val):
                if val[i] == '\\' and i+1 < len(val) and val[i+1] == '"':
                    i += 2
                    continue
                if val[i] == '"':
                    cnt += 1
                i += 1
            if cnt % 2 == 1:
                raise ValueError(f"line {line_no}: unterminated quote")
            return val

    last_line = {}
    for e in entries:
        last_line[(e['section'], e['key'])] = e['line_no']

    for sec, kvs in sections_final.items():
        for k in list(kvs.keys()):
            ln = last_line.get((sec, k), 0)
            kvs[k] = process_quotes(kvs[k], ln)

    resolved: dict[tuple[str, str], str] = {}
    visiting: set[tuple[str, str]] = set()

    def resolve(sec: str, key: str) -> str:
        if (sec, key) in resolved:
            return resolved[(sec, key)]
        if (sec, key) in visiting:
            raise ValueError(f"cycle detected involving {sec}:{key}")
        if sec not in sections_final or key not in sections_final[sec]:
            raise ValueError(f"undefined reference {sec}:{key}")
        visiting.add((sec, key))
        raw = sections_final[sec][key]
        result = interpolate(raw, sec)
        visiting.discard((sec, key))
        resolved[(sec, key)] = result
        return result

    def interpolate(val: str, current_sec: str) -> str:
        out = []
        i = 0
        n = len(val)
        while i < n:
            if val[i] == '$':
                if i+1 < n and val[i+1] == '$':
                    out.append('$')
                    i += 2
                    continue
                if i+1 < n and val[i+1] == '{':
                    j = val.find('}', i+2)
                    if j == -1:
                        out.append('$')
                        i += 1
                        continue
                    ref = val[i+2:j]
                    if ':' in ref:
                        ref_sec, ref_key = ref.split(':', 1)
                        ref_sec = ref_sec.strip()
                        ref_key = ref_key.strip().lower()
                    else:
                        ref_sec = current_sec
                        ref_key = ref.strip().lower()
                    out.append(resolve(ref_sec, ref_key))
                    i = j+1
                    continue
                out.append('$')
                i += 1
                continue
            out.append(val[i])
            i += 1
        return ''.join(out)

    for sec in list(sections_final.keys()):
        for key in list(sections_final[sec].keys()):
            sections_final[sec][key] = resolve(sec, key)

    return sections_final
