import re
from functools import total_ordering


@total_ordering
class Version:
    __slots__ = ("major", "minor", "patch", "prerelease", "build", "prerelease_ids")

    def __init__(self, major, minor, patch, prerelease="", build=""):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build
        if prerelease:
            self.prerelease_ids = prerelease.split(".")
        else:
            self.prerelease_ids = []

    def _cmp_key(self):
        return (self.major, self.minor, self.patch)

    def _compare(self, other):
        if self.major != other.major:
            return -1 if self.major < other.major else 1
        if self.minor != other.minor:
            return -1 if self.minor < other.minor else 1
        if self.patch != other.patch:
            return -1 if self.patch < other.patch else 1
        a = self.prerelease_ids
        b = other.prerelease_ids
        if not a and not b:
            return 0
        if not a:
            return 1
        if not b:
            return -1
        for x, y in zip(a, b):
            xnum = x.isdigit()
            ynum = y.isdigit()
            if xnum and ynum:
                xi = int(x)
                yi = int(y)
                if xi != yi:
                    return -1 if xi < yi else 1
            elif xnum and not ynum:
                return -1
            elif ynum and not xnum:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        return 0

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) == 0

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) < 0

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __repr__(self):
        s = "%d.%d.%d" % (self.major, self.minor, self.patch)
        if self.prerelease:
            s += "-" + self.prerelease
        if self.build:
            s += "+" + self.build
        return s


_VERSION_RE = re.compile(
    r"^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


def _parse_version_core(s):
    m = _VERSION_RE.match(s)
    if not m:
        raise ValueError("invalid version: %r" % (s,))
    major_s, minor_s, patch_s, pre, build = m.groups()
    for num_s in (major_s, minor_s, patch_s):
        if len(num_s) > 1 and num_s[0] == "0":
            raise ValueError("leading zero in version: %r" % (s,))
    if pre is not None:
        for ident in pre.split("."):
            if not ident:
                raise ValueError("empty prerelease identifier: %r" % (s,))
            if ident.isdigit() and len(ident) > 1 and ident[0] == "0":
                raise ValueError("leading zero in prerelease: %r" % (s,))
    if build is not None:
        for ident in build.split("."):
            if not ident:
                raise ValueError("empty build identifier: %r" % (s,))
    return Version(int(major_s), int(minor_s), int(patch_s), pre or "", build or "")


def parse(v):
    if not isinstance(v, str):
        raise ValueError("version must be a string")
    s = v.strip()
    if s.startswith("v") or s.startswith("="):
        s = s[1:].strip()
    return _parse_version_core(s)


# ---------------------------------------------------------------------------
# Range parsing
# ---------------------------------------------------------------------------

_PARTIAL_RE = re.compile(
    r"^(\d+|[xX*])(?:\.(\d+|[xX*])(?:\.(\d+|[xX*])"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?)?)?$"
)


class _Partial:
    """A possibly-partial version: components may be None (wildcard / missing)."""

    __slots__ = ("major", "minor", "patch", "prerelease", "build")

    def __init__(self, major, minor, patch, prerelease, build):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    def is_full(self):
        return self.major is not None and self.minor is not None and self.patch is not None

    def to_version(self):
        return Version(
            self.major or 0,
            self.minor or 0,
            self.patch or 0,
            self.prerelease or "",
            self.build or "",
        )


def _parse_partial(s):
    m = _PARTIAL_RE.match(s)
    if not m:
        raise ValueError("invalid partial version: %r" % (s,))
    major_s, minor_s, patch_s, pre, build = m.groups()

    def comp(x):
        if x is None:
            return None
        if x in ("x", "X", "*"):
            return None
        if len(x) > 1 and x[0] == "0":
            raise ValueError("leading zero: %r" % (s,))
        return int(x)

    major = comp(major_s)
    minor = comp(minor_s)
    patch = comp(patch_s)

    # Normalize wildcards: once a component is wildcard, later ones must be too.
    if major is None:
        minor = None
        patch = None
    elif minor is None:
        patch = None

    if pre is not None:
        if not (major is not None and minor is not None and patch is not None):
            raise ValueError("prerelease requires full version: %r" % (s,))
        for ident in pre.split("."):
            if not ident:
                raise ValueError("empty prerelease identifier: %r" % (s,))
            if ident.isdigit() and len(ident) > 1 and ident[0] == "0":
                raise ValueError("leading zero in prerelease: %r" % (s,))
    if build is not None:
        for ident in build.split("."):
            if not ident:
                raise ValueError("empty build identifier: %r" % (s,))

    return _Partial(major, minor, patch, pre, build)


class _Comparator:
    __slots__ = ("op", "version")

    def __init__(self, op, version):
        self.op = op
        self.version = version

    def matches(self, v):
        c = v._compare(self.version)
        op = self.op
        if op == "<":
            return c < 0
        if op == "<=":
            return c <= 0
        if op == ">":
            return c > 0
        if op == ">=":
            return c >= 0
        if op == "=":
            return c == 0
        raise AssertionError(op)

    def __repr__(self):
        return "%s%s" % (self.op, self.version)


def _xrange_to_comparators(op, p):
    """Convert an X-range (with an operator) into a list of comparators."""
    major = p.major
    minor = p.minor
    patch = p.patch

    if major is None:
        # * or X -> matches anything (with operator semantics)
        if op in ("", "="):
            return []
        if op == ">=":
            return [_Comparator(">=", Version(0, 0, 0))]
        if op == ">":
            return [_Comparator("<", Version(0, 0, 0))]  # matches nothing
        if op == "<=":
            return []  # anything >= 0.0.0 is <= infinity; treat as match-all
        if op == "<":
            return [_Comparator("<", Version(0, 0, 0))]  # nothing
        raise ValueError(op)

    if minor is None:
        # 1.x / 1
        lo = Version(major, 0, 0)
        hi = Version(major + 1, 0, 0)
        if op in ("", "="):
            return [_Comparator(">=", lo), _Comparator("<", hi)]
        if op == ">=":
            return [_Comparator(">=", lo)]
        if op == ">":
            return [_Comparator(">=", hi)]
        if op == "<":
            return [_Comparator("<", lo)]
        if op == "<=":
            return [_Comparator("<", hi)]
        raise ValueError(op)

    if patch is None:
        # 1.2.x / 1.2
        lo = Version(major, minor, 0)
        hi = Version(major, minor + 1, 0)
        if op in ("", "="):
            return [_Comparator(">=", lo), _Comparator("<", hi)]
        if op == ">=":
            return [_Comparator(">=", lo)]
        if op == ">":
            return [_Comparator(">=", hi)]
        if op == "<":
            return [_Comparator("<", lo)]
        if op == "<=":
            return [_Comparator("<", hi)]
        raise ValueError(op)

    # Full version
    v = p.to_version()
    if op == "":
        op = "="
    return [_Comparator(op, v)]


def _tilde_to_comparators(p):
    major = p.major
    minor = p.minor
    patch = p.patch
    if major is None:
        return []
    if minor is None:
        lo = Version(major, 0, 0)
        hi = Version(major + 1, 0, 0)
    elif patch is None:
        lo = Version(major, minor, 0)
        hi = Version(major, minor + 1, 0)
    else:
        lo = p.to_version()
        hi = Version(major, minor + 1, 0)
    return [_Comparator(">=", lo), _Comparator("<", hi)]


def _caret_to_comparators(p):
    major = p.major
    minor = p.minor
    patch = p.patch
    if major is None:
        return []
    if minor is None:
        lo = Version(major, 0, 0)
        if major == 0:
            hi = Version(1, 0, 0)
        else:
            hi = Version(major + 1, 0, 0)
        return [_Comparator(">=", lo), _Comparator("<", hi)]
    if patch is None:
        lo = Version(major, minor, 0)
        if major > 0:
            hi = Version(major + 1, 0, 0)
        elif minor > 0:
            hi = Version(0, minor + 1, 0)
        else:
            hi = Version(0, 1, 0)
        return [_Comparator(">=", lo), _Comparator("<", hi)]
    # Full
    lo = p.to_version()
    if major > 0:
        hi = Version(major + 1, 0, 0)
    elif minor > 0:
        hi = Version(0, minor + 1, 0)
    else:
        hi = Version(0, 0, patch + 1)
    return [_Comparator(">=", lo), _Comparator("<", hi)]


_HYPHEN_SPLIT_RE = re.compile(r"\s+-\s+")
_COMP_RE = re.compile(r"^([<>=]*)\s*(.*)$")


def _parse_comparator_token(token):
    m = _COMP_RE.match(token)
    if not m:
        raise ValueError("invalid comparator: %r" % (token,))
    op = m.group(1)
    rest = m.group(2).strip()
    if not rest:
        raise ValueError("missing version in comparator: %r" % (token,))
    if op not in ("", "<", "<=", ">", ">=", "=", "=="):
        raise ValueError("invalid operator: %r" % (op,))
    if op == "==":
        op = "="
    if rest[0] in "~^":
        if op != "":
            raise ValueError("invalid comparator: %r" % (token,))
        if rest[0] == "~":
            return _tilde_to_comparators(_parse_partial(rest[1:]))
        else:
            return _caret_to_comparators(_parse_partial(rest[1:]))
    p = _parse_partial(rest)
    return _xrange_to_comparators(op, p)


def _parse_hyphen(token):
    # token like "A - B"
    parts = _HYPHEN_SPLIT_RE.split(token)
    if len(parts) != 2:
        raise ValueError("invalid hyphen range: %r" % (token,))
    lo_s, hi_s = parts[0].strip(), parts[1].strip()
    lo_p = _parse_partial(lo_s)
    hi_p = _parse_partial(hi_s)

    result = []
    # Lower bound
    if lo_p.major is None:
        pass  # unbounded
    else:
        result.append(_Comparator(">=", lo_p.to_version()))

    # Upper bound
    if hi_p.major is None:
        pass
    elif hi_p.minor is None:
        result.append(_Comparator("<", Version(hi_p.major + 1, 0, 0)))
    elif hi_p.patch is None:
        result.append(_Comparator("<", Version(hi_p.major, hi_p.minor + 1, 0)))
    else:
        result.append(_Comparator("<=", hi_p.to_version()))

    return result


def _parse_comparator_set(s):
    s = s.strip()
    if s == "" or s == "*":
        return []

    # Detect hyphen range: must be a "A - B" where A and B are single tokens.
    if _HYPHEN_SPLIT_RE.search(s):
        # Hyphen range only if whole set is exactly a hyphen range
        parts = _HYPHEN_SPLIT_RE.split(s)
        if len(parts) == 2:
            # Make sure no extra spaces split comparators weirdly
            lo_tokens = parts[0].strip().split()
            hi_tokens = parts[1].strip().split()
            if len(lo_tokens) == 1 and len(hi_tokens) == 1:
                return _parse_hyphen(s)
        raise ValueError("invalid hyphen range: %r" % (s,))

    result = []
    for token in s.split():
        result.extend(_parse_comparator_token(token))
    return result


class _ComparatorSet:
    __slots__ = ("comparators",)

    def __init__(self, comparators):
        self.comparators = comparators

    def matches(self, v):
        for c in self.comparators:
            if not c.matches(v):
                return False
        if v.prerelease_ids:
            # Prerelease allowed only if some comparator has same core and a prerelease
            ok = False
            for c in self.comparators:
