from __future__ import annotations

import dataclasses
import types
import typing
from typing import (
    Any,
    Literal,
    Union,
    get_args,
    get_origin,
    get_type_hints,
)


class LoadError(ValueError):
    def __init__(self, path: str, message: str):
        self.path = path
        self.message = message
        super().__init__(f"{path}: {message}")

    def __str__(self) -> str:
        return f"{self.path}: {self.message}"


def _type_name(tp: Any) -> str:
    try:
        return tp.__name__
    except AttributeError:
        return str(tp)


def _join(path: str, part: str) -> str:
    if part.startswith("["):
        return path + part
    return path + "." + part


def _is_union(tp: Any) -> bool:
    origin = get_origin(tp)
    if origin is Union:
        return True
    if origin is types.UnionType:
        return True
    return False


def _load(tp: Any, data: Any, path: str) -> Any:
    # Handle None type
    if tp is None or tp is type(None):
        if data is None:
            return None
        raise LoadError(path, f"expected None, got {_type_name(type(data))}")

    origin = get_origin(tp)

    # Literal
    if origin is Literal:
        args = get_args(tp)
        for lit in args:
            if type(lit) is type(data) and lit == data:
                return data
        raise LoadError(path, f"value {data!r} is not one of {args!r}")

    # Union / Optional
    if _is_union(tp):
        args = get_args(tp)
        last_err: LoadError | None = None
        for member in args:
            try:
                return _load(member, data, path)
            except LoadError as e:
                last_err = e
        # None of them loaded
        raise LoadError(path, f"could not match any type in union")

    # Dataclass
    if isinstance(tp, type) and dataclasses.is_dataclass(tp):
        return _load_dataclass(tp, data, path)

    # Basic types
    if tp is int:
        if isinstance(data, bool) or not isinstance(data, int):
            raise LoadError(path, f"expected int, got {_type_name(type(data))}")
        return data

    if tp is float:
        if isinstance(data, bool):
            raise LoadError(path, f"expected float, got {_type_name(type(data))}")
        if isinstance(data, int):
            return float(data)
        if isinstance(data, float):
            return data
        raise LoadError(path, f"expected float, got {_type_name(type(data))}")

    if tp is str:
        if not isinstance(data, str):
            raise LoadError(path, f"expected str, got {_type_name(type(data))}")
        return data

    if tp is bool:
        if not isinstance(data, bool):
            raise LoadError(path, f"expected bool, got {_type_name(type(data))}")
        return data

    if tp is Any:
        return data

    # list[T]
    if origin is list:
        args = get_args(tp)
        if not isinstance(data, list):
            raise LoadError(path, f"expected list, got {_type_name(type(data))}")
        if not args:
            return list(data)
        elem_tp = args[0]
        return [_load(elem_tp, item, _join(path, f"[{i}]")) for i, item in enumerate(data)]

    # dict[str, T]
    if origin is dict:
        args = get_args(tp)
        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict, got {_type_name(type(data))}")
        if not args:
            return dict(data)
        key_tp, val_tp = args
        result = {}
        for k, v in data.items():
            new_key = _load(key_tp, k, _join(path, str(k)))
            new_val = _load(val_tp, v, _join(path, str(k)))
            result[new_key] = new_val
        return result

    # tuple
    if origin is tuple:
        args = get_args(tp)
        if not isinstance(data, list):
            raise LoadError(path, f"expected list for tuple, got {_type_name(type(data))}")
        if not args:
            return tuple(data)
        # tuple[T, ...]
        if len(args) == 2 and args[1] is Ellipsis:
            elem_tp = args[0]
            return tuple(
                _load(elem_tp, item, _join(path, f"[{i}]"))
                for i, item in enumerate(data)
            )
        # fixed length
        if len(data) != len(args):
            raise LoadError(
                path, f"expected tuple of length {len(args)}, got length {len(data)}"
            )
        return tuple(
            _load(arg_tp, item, _join(path, f"[{i}]"))
            for i, (arg_tp, item) in enumerate(zip(args, data))
        )

    raise LoadError(path, f"unsupported annotation {tp!r}")


def _load_dataclass(cls: type, data: Any, path: str) -> Any:
    if not isinstance(data, dict):
        raise LoadError(path, f"expected object, got {_type_name(type(data))}")

    try:
        hints = get_type_hints(cls)
    except Exception:
        hints = {}

    fields = dataclasses.fields(cls)
    field_names = {f.name for f in fields}

    # Unknown keys (in input order)
    for key in data:
        if key not in field_names:
            raise LoadError(_join(path, str(key)), "unknown field")

    kwargs = {}
    for f in fields:
        fpath = _join(path, f.name)
        if f.name in data:
            tp = hints.get(f.name, f.type)
            kwargs[f.name] = _load(tp, data[f.name], fpath)
        else:
            if f.default is not dataclasses.MISSING:
                kwargs[f.name] = f.default
            elif f.default_factory is not dataclasses.MISSING:
                kwargs[f.name] = f.default_factory()
            else:
                raise LoadError(fpath, "missing required field")

    return cls(**kwargs)


def load(cls: type, data: Any) -> Any:
    return _load(cls, data, "$")
