        args = get_args(tp)
        if not isinstance(data, list):
            raise LoadError(path, f"expected list, got {_type_name(type(data))}")
        if not args:
            return list(data)
        elem_tp = args[0]
        return [_load(elem_tp, item, _join(path, f"[{i}]")) for i, item in enumerate(data)]

    # dict[str, T]
    if origin is dict:
        args = get_args(tp)
        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict, got {_type_name(type(data))}")
        if not args:
            return dict(data)
        key_tp, val_tp = args
        result = {}
        for k, v in data.items():
            new_key = _load(key_tp, k, _join(path, str(k)))
            new_val = _load(val_tp, v, _join(path, str(k)))
            result[new_key] = new_val
        return result

    # tuple
    if origin is tuple:
        args = get_args(tp)
        if not isinstance(data, list):
            raise LoadError(path, f"expected list for tuple, got {_type_name(type(data))}")
        if not args:
            return tuple(data)
        # tuple[T, ...]
        if len(args) == 2 and args[1] is Ellipsis:
            elem_tp = args[0]
            return tuple(
                _load(elem_tp, item, _join(path, f"[{i}]"))
                for i, item in enumerate(data)
            )
        # fixed length
        if len(data) != len(args):
            raise LoadError(
                path, f"expected tuple of length {len(args)}, got length {len(data)}"
            )
        return tuple(
            _load(arg_tp, item, _join(path, f"[{i}]"))
            for i, (arg_tp, item) in enumerate(zip(args, data))
        )

    raise LoadError(path, f"unsupported annotation {tp!r}")


def _load_dataclass(cls: type, data: Any, path: str) -> Any:
    if not isinstance(data, dict):
        raise LoadError(path, f"expected object, got {_type_name(type(data))}")

    try:
        hints = get_type_hints(cls)
    except Exception:
        hints = {}

    fields = dataclasses.fields(cls)
    field_names = {f.name for f in fields}

    # Unknown keys (in input order)
    for key in data:
        if key not in field_names:
            raise LoadError(_join(path, str(key)), "unknown field")

    kwargs = {}
    for f in fields:
        fpath = _join(path, f.name)
        if f.name in data:
            tp = hints.get(f.name, f.type)
            kwargs[f.name] = _load(tp, data[f.name], fpath)
        else:
            if f.default is not dataclasses.MISSING:
                kwargs[f.name] = f.default
            elif f.default_factory is not dataclasses.MISSING:
                kwargs[f.name] = f.default_factory()
            else:
                raise LoadError(fpath, "missing required field")

    return cls(**kwargs)


def load(cls: type, data: Any) -> Any:
    return _load(cls, data, "$")
