#!/usr/bin/env bash
# Summarize web server access logs in combined log format.

set -u

# ---- check inputs first: any missing file -> stderr + exit 1, no output ----
for arg in "$@"; do
    if [ "$arg" != "-" ] && [ ! -e "$arg" ]; then
        echo "solution.sh: cannot open '$arg': No such file or directory" >&2
        exit 1
    fi
done

if [ "$#" -eq 0 ]; then
    echo "usage: solution.sh LOGFILE..." >&2
    exit 1
fi

# ---- read all logs into awk ----
# We pass files to awk; gz handled via zcat through process substitution
# wrapped in a helper. To keep awk POSIX-only, do the parsing in awk but
# feed it a unified stream.

read_logs() {
    local f
    for f in "$@"; do
        if [ "$f" = "-" ]; then
            cat
        elif [[ "$f" == *.gz ]]; then
            zcat -- "$f"
        else
            cat -- "$f"
        fi
    done
}

read_logs "$@" | awk '
BEGIN {
    req = 0; mal = 0;
    # status[code] counts, ipbytes[ip], pathcnt[path]
}

{
    line = $0
    # Combined log format:
    # host ident authuser [date] "request" status size "referer" "user-agent"
    # We parse strictly.

    # 1) host: first field, non-empty, no spaces
    if (!match(line, /^[^ ]+ /)) { mal++; next }
    host = substr(line, 1, RLENGTH - 1)
    rest = substr(line, RLENGTH + 1)

    # 2) ident
    if (!match(rest, /^[^ ]+ /)) { mal++; next }
    rest = substr(rest, RLENGTH + 1)

    # 3) authuser
    if (!match(rest, /^[^ ]+ /)) { mal++; next }
    rest = substr(rest, RLENGTH + 1)

    # 4) [date time]
    if (!match(rest, /^\[[^]]*\] /)) { mal++; next }
    rest = substr(rest, RLENGTH + 1)

    # 5) "request"
    # request is quoted; must contain no unescaped quote; allow any chars except quote
    if (!match(rest, /^"[^"]*" /)) { mal++; next }
    reqstr = substr(rest, 2, RLENGTH - 3)   # strip leading " and trailing " and space
    rest = substr(rest, RLENGTH + 1)

    # 6) status: numeric
    if (!match(rest, /^[0-9]+ /)) { mal++; next }
    status = substr(rest, 1, RLENGTH - 1)
    rest = substr(rest, RLENGTH + 1)

    # 7) size: numeric or "-"
    if (!match(rest, /^[^ ]+ /)) { mal++; next }
    size = substr(rest, 1, RLENGTH - 1)
    rest = substr(rest, RLENGTH + 1)
    if (size == "-") {
        size = 0
    } else if (size !~ /^[0-9]+$/) {
        mal++; next
    } else {
        size = size + 0
    }

    # 8) "referer"
    if (!match(rest, /^"[^"]*" /)) { mal++; next }
    rest = substr(rest, RLENGTH + 1)

    # 9) "user-agent" (to end of line)
    if (!match(rest, /^"[^"]*"$/)) { mal++; next }

    # ---- valid line ----
    req++
    status_cnt[status]++
    ip_bytes[host] += size

    # path: request line -> method SP target SP proto ; take target, strip query
    path = reqstr
    n = split(path, parts, " ")
    if (n >= 2) {
        target = parts[2]
    } else {
        target = ""
    }
    q = index(target, "?")
    if (q > 0) target = substr(target, 1, q - 1)
    if (target != "") path_cnt[target]++
}

END {
    printf "requests: %d\n", req
    printf "malformed: %d\n", mal

    printf "status:\n"
    # collect codes, sort ascending numerically
    nst = 0
    for (c in status_cnt) codes[++nst] = c
    for (i = 2; i <= nst; i++) {
        v = codes[i]; j = i - 1
        while (j >= 1 && (codes[j] + 0) > (v + 0)) { codes[j+1] = codes[j]; j-- }
        codes[j+1] = v
    }
    for (i = 1; i <= nst; i++) {
        printf "  %s %d\n", codes[i], status_cnt[codes[i]]
    }

    printf "top_ips:\n"
    # sort ips by bytes desc, tie ip asc (byte order -> string compare)
    nip = 0
    for (ip in ip_bytes) ips[++nip] = ip
    for (i = 2; i <= nip; i++) {
        v = ips[i]; vb = ip_bytes[v]; j = i - 1
        while (j >= 1) {
            u = ips[j]; ub = ip_bytes[u]
            # need u before v ?  u should come first if ub > vb, or ub==vb and u < v
            if (ub > vb || (ub == vb && u <= v)) break
            ips[j+1] = ips[j]; j--
        }
        ips[j+1] = v
    }
    lim = (nip < 3) ? nip : 3
    for (i = 1; i <= lim; i++) {
        printf "  %s %d\n", ips[i], ip_bytes[ips[i]]
    }

    printf "top_paths:\n"
    npa = 0
    for (p in path_cnt) paths[++npa] = p
    for (i = 2; i <= npa; i++) {
        v = paths[i]; vc = path_cnt[v]; j = i - 1
        while (j >= 1) {
            u = paths[j]; uc = path_cnt[u]
            # u should come first if uc > vc, or uc==vc and u < v
            if (uc > vc || (uc == vc && u <= v)) break
            paths[j+1] = paths[j]; j--
        }
        paths[j+1] = v
    }
    lim = (npa < 3) ? npa : 3
    for (i = 1; i <= lim; i++) {
        printf "  %s %d\n", paths[i], path_cnt[paths[i]]
    }
}
'
