#!/usr/bin/env bash
# solution.sh [-d DELIM] [-s] COLUMN [FILE]

set -u

DELIM=','
SUMMARIZE=0

usage() {
    echo "usage: $0 [-d DELIM] [-s] COLUMN [FILE]" >&2
    exit 2
}

while getopts ":d:s" opt; do
    case "$opt" in
        d)
            DELIM="$OPTARG"
            if [ "${#DELIM}" -ne 1 ]; then
                echo "error: delimiter must be a single character" >&2
                exit 2
            fi
            ;;
        s) SUMMARIZE=1 ;;
        *) usage ;;
    esac
done
shift $((OPTIND - 1))

if [ "$#" -lt 1 ] || [ "$#" -gt 2 ]; then
    usage
fi

COLUMN="$1"
FILE="${2:-}"

if [ -n "$FILE" ]; then
    if [ ! -f "$FILE" ]; then
        echo "error: cannot open file: $FILE" >&2
        exit 2
    fi
fi

exec awk -v delim="$DELIM" -v column="$COLUMN" -v summarize="$SUMMARIZE" '
BEGIN {
    dlen = length(delim)
    dch = substr(delim, 1, 1)
    state = "start"     # start, unquoted, quoted
    field = ""
    nfields = 0
    nrows = 0
    header_done = 0
    target = -1
    unterminated = 0
    saw_cr = 0
    # numeric tracking
    count = 0
    sum = 0
    have_min = 0
    minv = 0
    maxv = 0
    out = ""
}

function end_field() {
    nfields++
    if (nrows == 0) {
        if (header_done == 0) {
            header[nfields] = field
        }
    } else if (header_done == 1) {
        process_value(field)
    }
    field = ""
}

function process_value(v) {
    if (summarize == 1) {
        if (v == "") return
        # validate numeric: optional sign, digits, optional decimal
        if (v !~ /^[-+]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$/) return
        num = v + 0
        count++
        sum += num
        if (have_min == 0) {
            minv = num
            maxv = num
            have_min = 1
        } else {
            if (num < minv) minv = num
            if (num > maxv) maxv = num
        }
    } else {
        gsub(/\n/, "\\n", v)
        out = out v "\n"
    }
}

function end_row() {
    # flush last field
    if (state == "quoted") {
        unterminated = 1
        return
    }
    end_field()
    if (nrows == 0) {
        # header row: resolve target
        header_done = 1
        if (column ~ /^#[0-9]+$/) {
            idx = substr(column, 2) + 0
            if (idx >= 1) target = idx
        } else {
            for (i = 1; i <= nfields; i++) {
                if (header[i] == column) { target = i; break }
            }
        }
        if (target < 0) {
            unknown = 1
            exit 3
        }
    } else {
        if (target > 0 && target <= nfields) {
            # already processed in end_field; nothing to do
        }
    }
    nrows++
    nfields = 0
    state = "start"
    field = ""
}

# We need to process values only for the target column.
# Rewrite: end_field checks column index.

function end_field2() {
    nfields++
    if (nrows == 0) {
        if (header_done == 0) header[nfields] = field
    } else if (header_done == 1 && nfields == target) {
        process_value(field)
    }
    field = ""
}

{
    line = $0
    # process char by char
    len = length(line)
    for (i = 1; i <= len; i++) {
        c = substr(line, i, 1)
        if (state == "quoted") {
            if (c == "\"") {
                # peek next
                if (i < len && substr(line, i+1, 1) == "\"") {
                    field = field "\""
                    i++
                } else {
                    state = "afterquote"
                }
            } else {
                field = field c
            }
        } else if (state == "afterquote") {
            # after closing quote; should be delimiter or end
            if (c == dch) {
                end_field2()
                state = "start"
            } else {
                # malformed; treat as content? RFC strict. Just append.
                field = field c
                state = "unquoted"
            }
        } else if (state == "start") {
            if (c == "\"") {
                state = "quoted"
            } else if (c == dch) {
                end_field2()
                state = "start"
            } else {
                field = field c
                state = "unquoted"
            }
        } else { # unquoted
            if (c == dch) {
                end_field2()
                state = "start"
            } else {
                field = field c
            }
        }
    }
    # end of line: if quoted, continue to next line (embedded newline)
    if (state == "quoted") {
        field = field "\n"
        next
    }
    # end row
    end_field2()
    if (nrows == 0) {
        header_done = 1
        if (column ~ /^#[0-9]+$/) {
            idx = substr(column, 2) + 0
            if (idx >= 1) target = idx
        } else {
            target = -1
            for (i = 1; i <= nfields; i++) {
                if (header[i] == column) { target = i; break }
            }
        }
        if (target < 0) {
            print "error: unknown column: " column > "/dev/stderr"
            exit 3
        }
    }
    nrows++
    nfields = 0
    state = "start"
    field = ""
}

END {
    if (unterminated || state == "quoted") {
        print "error: unterminated quote" > "/dev/stderr"
        exit 4
    }
    # If no data rows and header processed
    if (nrows == 0) {
        # no header at all - unknown column
        print "error: unknown column: " column > "/dev/stderr"
        exit 3
    }
    if (summarize == 1) {
        if (count == 0) {
            printf "count=0\n"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum, minv, maxv
        }
    } else {
        printf "%s", out
    }
}
' "$FILE"
