#!/usr/bin/env bash
# Count regular files under DIR recursively by (lowercased) extension.
# Output: "EXT COUNT" lines, sorted by count desc, then extension asc (byte order).

if [ "$#" -ne 1 ]; then
    echo "usage: $0 DIR" >&2
    exit 1
fi

dir=$1

if [ ! -d "$dir" ]; then
    echo "$0: '$dir' is not a directory" >&2
    exit 1
fi

find "$dir" \
    \( -type d \( -name .git -o -name node_modules \) -prune \) \
    -o -type f -print0 |
awk -v RS='\0' '
{
    n = $0
    sub(/^.*\//, "", n)
    # Only dot that is the leading one => (none)
    if (match(n, /\.[^.]*$/)) {
        ext = substr(n, RSTART + 1)
        # If the dot is the first character of the basename, it is a hidden file => (none)
        if (RSTART == 1) {
            ext = "(none)"
        } else {
            ext = tolower(ext)
        }
    } else {
        ext = "(none)"
    }
    count[ext]++
}
END {
    for (e in count) print count[e] "\t" e
}' |
LC_ALL=C sort -t $'\t' -k1,1nr -k2,2 |
awk -F '\t' '{ print $2 " " $1 }'
```

Key fix: when the matched dot is the first character of the basename (`RSTART == 1`), it's a leading-only dot (e.g. `.bashrc`), which must count as `(none)` rather than as extension `bashrc`.

