#!/usr/bin/env bash
# solution.sh FILE
# Converts a dotenv file into safe-to-eval bash shell code.

set -u

if [ "$#" -ne 1 ]; then
    echo "usage: $0 FILE" >&2
    exit 2
fi

FILE=$1

if [ ! -r "$FILE" ]; then
    echo "$0: cannot read $FILE" >&2
    exit 2
fi

awk -v file="$FILE" '
function is_key(s) {
    return (s ~ /^[A-Za-z_][A-Za-z0-9_]*$/)
}
# Escape single quotes for safe single-quoted shell string.
function shquote(s) {
    gsub(/\047/, "\047\\\047\047", s)
    return "\047" s "\047"
}
# Check that trailing part after closing quote is empty or a comment.
function valid_tail(s) {
    if (s == "") return 1
    if (s ~ /^[ \t]+#/) return 1
    if (s ~ /^[ \t]+$/) return 1
    return 0
}
{
    line = $0
    # Strip trailing CR (for CRLF files).
    sub(/\r$/, "", line)
    raw[NR] = line

    # Skip blank lines and comment lines (first non-blank char is #).
    if (line ~ /^[ \t]*$/) next
    if (line ~ /^[ \t]*#/) next

    s = line
    # Optional leading whitespace then optional "export " then key.
    sub(/^[ \t]*/, "", s)
    exported = 0
    if (substr(s, 1, 7) == "export ") {
        s = substr(s, 8)
        exported = 1
    }
    # Extract key up to '='.
    eq = index(s, "=")
    if (eq == 0) { invalid = NR; exit }
    key = substr(s, 1, eq - 1)
    if (!is_key(key)) { invalid = NR; exit }
    val = substr(s, eq + 1)

    # Determine value form.
    if (substr(val, 1, 1) == "\047") {
        # Single-quoted: find closing quote.
        rest = substr(val, 2)
        # Find first unescaped single quote... in single quotes there are no escapes;
        # the value ends at the next single quote.
        idx = index(rest, "\047")
        if (idx == 0) { invalid = NR; exit }
        content = substr(rest, 1, idx - 1)
        tail = substr(rest, idx + 1)
        if (!valid_tail(tail)) { invalid = NR; exit }
        value = content
    } else if (substr(val, 1, 1) == "\"") {
        # Double-quoted: parse escapes.
        rest = substr(val, 2)
        content = ""
        closed = 0
        i = 1
        n = length(rest)
        while (i <= n) {
            c = substr(rest, i, 1)
            if (c == "\\") {
                if (i + 1 > n) { invalid = NR; exit }
                d = substr(rest, i + 1, 1)
                if (d == "n") content = content "\n"
                else if (d == "\"") content = content "\""
                else if (d == "\\") content = content "\\"
                else content = content "\\" d
                i += 2
            } else if (c == "\"") {
                closed = 1
                i++
                break
            } else {
                content = content c
                i++
            }
        }
        if (!closed) { invalid = NR; exit }
        tail = substr(rest, i)
        if (!valid_tail(tail)) { invalid = NR; exit }
        value = content
    } else {
        # Unquoted: literal up to " #" (space then hash starts comment).
        # Also trim trailing spaces and tabs.
        # Find first occurrence of space followed by '#'.
        pos = 0
        m = length(val)
        j = 1
        while (j < m) {
            if (substr(val, j, 1) == " " && substr(val, j + 1, 1) == "#") {
                pos = j
                break
            }
            j++
        }
        if (pos > 0) value = substr(val, 1, pos - 1)
        else value = val
        # Trim trailing spaces and tabs.
        sub(/[ \t]+$/, "", value)
        # Also trim leading spaces/tabs? Spec says value taken literally up to comment.
        # No mention of leading trim for unquoted, keep literal.
    }

    # Record: later value wins, keeps later position.
    if (!(key in seen)) {
        order[++count] = key
        seen[key] = 1
    }
    values[key] = value
}
END {
    if (invalid) {
        printf "%s:%d: invalid line\n", file, invalid > "/dev/stderr"
        exit 1
    }
    for (k = 1; k <= count; k++) {
        key = order[k]
        print "export " key "=" shquote(values[key])
    }
}
' "$FILE"
```

Notes on the implementation:

- **Validation first, output second**: awk collects everything into arrays; if any line is invalid it prints the error and exits 1 before emitting anything, guaranteeing no stdout on failure.
- **Unquoted values**: scanning stops at the first space-then-`#` sequence (` #`), so `a#b` keeps the hash. Trailing spaces/tabs are trimmed.
- **Single quotes**: content is taken literally between the first pair of quotes; trailing part must be empty, whitespace, or ` #…`.
- **Double quotes**: `\n`, `\"`, `\\` are translated; any other backslash sequence is kept verbatim (backslash + char). No expansion is performed. Trailing part validated the same way.
- **Output**: every value is single-quoted, with embedded `'` replaced by `'\''` via `shquote`.
- **Duplicates**: the key list keeps first-seen order for the key, but the value stored is overwritten each time — so the later value wins while the key is printed once at its last value's position in the list (which is its first occurrence position; since each key appears once in `order`, the position is stable and the value is the last one). If you need strictly "later position" ordering (i.e., a repeated key moves to the end), replace the `order` bookkeeping accordingly — the spec's "keeps its LATER position" is satisfied here by printing once at the key's single recorded slot with the latest value; to reorder on repeat, delete and re-append the key to `order` on each occurrence.

```bash
#!/usr/bin/env bash
# solution.sh FILE
# Converts a dotenv file into safe-to-eval bash shell code.

set -u

if [ "$#" -ne 1 ]; then
    echo "usage: $0 FILE" >&2
    exit 2
fi

FILE=$1

if [ ! -r "$FILE" ]; then
    echo "$0: cannot read $FILE" >&2
    exit 2
fi

awk -v file="$FILE" '
function is_key(s) {
    return (s ~ /^[A-Za-z_][A-Za-z0-9_]*$/)
}
# Escape single quotes for safe single-quoted shell string.
function shquote(s) {
    gsub(/\047/, "\047\\\047\047", s)
    return "\047" s "\047"
}
# Check that trailing part after closing quote is empty or a comment.
function valid_tail(s) {
    if (s == "") return 1
    if (s ~ /^[ \t]+#/) return 1
    if (s ~ /^[ \t]+$/) return 1
    return 0
}
{
    line = $0
    # Strip trailing CR (for CRLF files).
    sub(/\r$/, "", line)

    # Skip blank lines and comment lines (first non-blank char is #).
    if (line ~ /^[ \t]*$/) next
    if (line ~ /^[ \t]*#/) next

    s = line
    # Optional leading whitespace then optional "export " then key.
    sub(/^[ \t]*/, "", s)
    if (substr(s, 1, 7) == "export ") {
        s = substr(s, 8)
    }
    # Extract key up to '='.
    eq = index(s, "=")
    if (eq == 0) { invalid = NR; exit }
    key = substr(s, 1, eq - 1)
    if (!is_key(key)) { invalid = NR; exit }
    val = substr(s, eq + 1)

    # Determine value form.
    if (substr(val, 1, 1) == "\047") {
        # Single-quoted: find closing quote.
        rest = substr(val, 2)
        idx = index(rest, "\047")
        if (idx == 0) { invalid = NR; exit }
        content = substr(rest, 1, idx - 1)
        tail = substr(rest, idx + 1)
        if (!valid_tail(tail)) { invalid = NR; exit }
        value = content
    } else if (substr(val, 1, 1) == "\"") {
        # Double-quoted: parse escapes.
        rest = substr(val, 2)
        content = ""
        closed = 0
        i = 1
        n = length(rest)
        while (i <= n) {
            c = substr(rest, i, 1)
            if (c == "\\") {
                if (i + 1 > n) { invalid = NR; exit }
                d = substr(rest, i + 1, 1)
                if (d == "n") content = content "\n"
                else if (d == "\"") content = content "\""
                else if (d == "\\") content = content "\\"
                else content = content "\\" d
                i += 2
            } else if (c == "\"") {
                closed = 1
                i++
                break
            } else {
                content = content c
                i++
            }
        }
        if (!closed) { invalid = NR; exit }
        tail = substr(rest, i)
        if (!valid_tail(tail)) { invalid = NR; exit }
        value = content
    } else {
        # Unquoted: literal up to " #" (space then hash starts comment).
        # Also trim trailing spaces and tabs.
        pos = 0
        m = length(val)
        j = 1
        while (j < m) {
            if (substr(val, j, 1) == " " && substr(val, j + 1, 1) == "#") {
                pos = j
                break
            }
            j++
        }
        if (pos > 0) value = substr(val, 1, pos - 1)
        else value = val
        # Trim trailing spaces and tabs.
        sub(/[ \t]+$/, "", value)
    }

    # Record: later value wins, and key moves to its LATER position.
    if (!(key in seen)) {
        seen[key] = 1
        order[++count] = key
    } else {
        # Remove key from order and re-append to move it to the end.
        for (k = 1; k <= count; k++) {
            if (order[k] == key) {
                for (j = k; j < count; j++) order[j] = order[j + 1]
                order[count] = key
                break
            }
        }
    }
    values[key] = value
}
END {
    if (invalid) {
        printf "%s:%d: invalid line\n", file, invalid > "/dev/stderr"
        exit 1
    }
    for (k = 1; k <= count; k++) {
        key = order[k]
        print "export " key "=" shquote(values[key])
    }
}
' "$FILE"
```
